import itertools, sys
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# build all valid triples (a,b,c) with a<b and a+b=c
triples = []
for a, b in itertools.combinations(L, 2):
    c = a + b
    if c in L and c not in (a, b):
        triples.append((a, b, c))
# exact cover search
used = set()
solution = []

def backtrack(start):
    if len(solution) == 15:
        return True
    for i in range(start, len(triples)):
        a, b, c = triples[i]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a, b, c])
        solution.append((a, b, c))
        if backtrack(i + 1):
            return True
        # undo
        used.difference_update([a, b, c])
        solution.pop()
    return False

found = backtrack(0)
if not found:
    print('No partition exists')
    sys.exit(0)
print('Partition found:')
for tri in solution:
    print(tri)
# witness output
import json
witness = {
    "polarity": "positive",
    "evidence": {"path": "execution://witness"},
    "data": {"triples": solution}
}
print('WITNESS:', json.dumps(witness))

# Python program to find a partition of the given set into triples (a,b,c) with a+b=c
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Pre‑compute all possible triples (a,b,c) where a<b and a+b=c and all three are in L
triples = [(a, b, a+b) for a in L for b in L if a < b and a+b in L]

# Index numbers to triples that contain them for faster lookup
from collections import defaultdict
num_to_triples = defaultdict(list)
for t in triples:
    for x in t:
        num_to_triples[x].append(t)

solution = None

def backtrack(remaining, chosen):
    global solution
    if solution is not None:
        return True
    if not remaining:
        solution = list(chosen)
        return True
    # choose the smallest remaining number to reduce branching
    x = min(remaining)
    for t in num_to_triples[x]:
        a,b,c = t
        if a in remaining and b in remaining and c in remaining:
            new_rem = remaining - {a,b,c}
            if backtrack(new_rem, chosen+[t]):
                return True
    return False

backtrack(set(L), [])

if solution is not None:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
    import json, sys
    print("WITNESS: " + json.dumps(witness))
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "proof", "argument": "No partition exists for the given set."}
    import json, sys
    print("WITNESS: " + json.dumps(witness))
